import "core-js/modules/es.array.push.js";
import { ref, onMounted, onBeforeUnmount } from 'vue';
import axios from 'axios';
import * as echarts from 'echarts';
import DockerContainers from '@/components/Container/DockerContainers.vue';
export default {
  __name: 'MonitorView',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const containersRef = ref(null);
    const selectedContainer = ref('');
    const containers = ref([]);
    const bandwidthChartRef = ref(null);
    const networkChartRef = ref(null);
    let bandwidthChart = null;
    let networkChart = null;
    let intervalId = null;

    // 初始化图表数据数组
    const bandwidthData = ref([]);
    const timeData = ref([]);
    const rxData = ref([]);
    const txData = ref([]);
    const fetchContainers = async () => {
      try {
        const res = await axios.get('http://localhost:8081/container/list');
        containers.value = containersRef.value.containers || [];
      } catch (err) {
        console.error('获取容器列表失败', err);
      }
    };
    const startMonitoring = () => {
      clearInterval(intervalId);
      bandwidthData.value = [];
      timeData.value = [];
      rxData.value = [];
      txData.value = [];
      updateCharts();
      intervalId = setInterval(async () => {
        if (!selectedContainer.value) return;
        const timestamp = new Date().toLocaleTimeString();
        try {
          const bandwidthRes = await axios.get(`http://localhost:8081/stats/bandwidth/${selectedContainer.value}?interval=1000`);
          const statsRes = await axios.get(`http://localhost:8081/stats/networkStats/${selectedContainer.value}`);
          timeData.value.push(timestamp);
          bandwidthData.value.push(bandwidthRes.data.totalRate);
          rxData.value.push(statsRes.data.rxBytes);
          txData.value.push(statsRes.data.txBytes);
          if (timeData.value.length > 20) {
            timeData.value.shift();
            bandwidthData.value.shift();
            rxData.value.shift();
            txData.value.shift();
          }
          updateCharts();
        } catch (err) {
          console.error('监控数据获取失败', err);
        }
      }, 1000);
    };
    const updateCharts = () => {
      if (!bandwidthChart || !networkChart) {
        bandwidthChart = echarts.init(bandwidthChartRef.value);
        networkChart = echarts.init(networkChartRef.value);
      }
      bandwidthChart.setOption({
        title: {
          text: '容器带宽使用率 (Bytes/s)'
        },
        xAxis: {
          type: 'category',
          data: timeData.value
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          data: bandwidthData.value,
          type: 'line',
          name: '总带宽',
          smooth: true
        }]
      });
      networkChart.setOption({
        title: {
          text: '网络收发字节数 (累计)'
        },
        tooltip: {
          trigger: 'axis'
        },
        legend: {
          data: ['接收字节 RX', '发送字节 TX']
        },
        xAxis: {
          type: 'category',
          data: timeData.value
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          data: rxData.value,
          type: 'line',
          name: '接收字节 RX',
          smooth: true
        }, {
          data: txData.value,
          type: 'line',
          name: '发送字节 TX',
          smooth: true
        }]
      });
    };
    onMounted(() => {
      fetchContainers();
    });
    onBeforeUnmount(() => {
      clearInterval(intervalId);
    });
    const __returned__ = {
      containersRef,
      selectedContainer,
      containers,
      bandwidthChartRef,
      networkChartRef,
      get bandwidthChart() {
        return bandwidthChart;
      },
      set bandwidthChart(v) {
        bandwidthChart = v;
      },
      get networkChart() {
        return networkChart;
      },
      set networkChart(v) {
        networkChart = v;
      },
      get intervalId() {
        return intervalId;
      },
      set intervalId(v) {
        intervalId = v;
      },
      bandwidthData,
      timeData,
      rxData,
      txData,
      fetchContainers,
      startMonitoring,
      updateCharts,
      ref,
      onMounted,
      onBeforeUnmount,
      get axios() {
        return axios;
      },
      get echarts() {
        return echarts;
      },
      DockerContainers
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
